//! 🧪️ Actual allocation and post failures keep their original owner.
use super::*;
use crate::native_decoding::{NativeDecodeAllocationEvent,NativeDecodeAllocationIssuer};
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
fn close<T:crate::retirement::RetireOwned>(value:T){let grant=crate::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();while !owner.terminal_is_empty(){owner.step(grant).unwrap();}}
#[test]
fn slot_posts_real_allocator_failure_and_retains_post_refusal(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let case=fixture["allocationSettlement"].as_array().unwrap().iter().find(|row|row["name"]=="allocationAndPostRefused").unwrap();let prior=case["prior"].as_u64().unwrap()as usize;let request=case["requested"].as_u64().unwrap()as usize;let admitted=AtomicUsize::new(0);let posted=AtomicUsize::new(usize::MAX);let deny=AtomicBool::new(false);let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(quote)=>{assert_eq!(quote.owned_bytes,admitted.load(Ordering::Relaxed));Ok(())},NativeDecodeAllocationEvent::Post{request,actual}=>{admitted.store(request.next_owned_bytes,Ordering::Relaxed);posted.store(actual,Ordering::Relaxed);if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused"))}else{Ok(())}},NativeDecodeAllocationEvent::Cancel(_)=>if deny.load(Ordering::Relaxed){Err(ValueError::literal(ValueRefusalKind::Canceled,"cancel refused"))}else{Ok(())}};let mut loan_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=loan_issuer.loan(&mut port);let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(prior+request,&mut progress,&mut loan);let mut prior_owner=Vec::<u8>::new();let mut unwind=None;native.allocate_vec_into(prior,&mut prior_owner,&mut unwind).unwrap();deny.store(true,Ordering::Relaxed);let mut output=Vec::<u8>::new();let((result,attempts),physical)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||native.allocate_vec_into(request,&mut output,&mut unwind)));let failure=result.unwrap_err();assert_eq!(attempts,1);assert_eq!(physical,(0,0));assert_eq!(failure.primary.as_ref().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(failure.forwarded_cancel.as_ref().unwrap().message.as_ref(),"cancel refused");assert_eq!(failure.progress.actual_capacity_bytes,None);assert_eq!(failure.progress.admitted_bytes,prior);assert_eq!(native.owned_bytes(),prior);assert_eq!(admitted.load(Ordering::Relaxed),prior);assert_eq!(posted.load(Ordering::Relaxed),prior);assert!(output.is_empty());assert_eq!(output.capacity(),0);assert!(unwind.is_none());drop(native);close(prior_owner);close(output);close(failure);
}
#[test]
fn slot_retains_born_owner_when_original_post_refuses(){
 let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(_)=>Ok(()),NativeDecodeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused")),NativeDecodeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut loan_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=loan_issuer.loan(&mut port);let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut progress,&mut loan);let mut output=Vec::<u8>::new();let mut unwind=None;let failure=native.allocate_vec_into(5,&mut output,&mut unwind).unwrap_err();assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.forwarded_post.as_ref().unwrap().message.as_ref(),"post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);
}

#[test]
fn text_slot_retains_original_backing_on_post_refusal(){
 let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(_)=>Ok(()),NativeDecodeAllocationEvent::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"text post refused")),NativeDecodeAllocationEvent::Cancel(_)=>panic!("unexpected cancellation")};let mut loan_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=loan_issuer.loan(&mut port);let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut progress,&mut loan);let mut output=String::new();let mut unwind=None;let failure=native.reserve_text_into(5,&mut output,&mut unwind).unwrap_err();assert!(output.is_empty());assert_eq!(output.capacity(),5);assert_eq!(failure.progress.actual_capacity_bytes,Some(output.capacity()));assert_eq!(failure.forwarded_post.as_ref().unwrap().message.as_ref(),"text post refused");assert!(unwind.is_none());drop(native);close(output);close(failure);
}

#[test]
fn caller_slot_and_original_callback_phase_survive_post_unwind(){
 let verdict=std::sync::Mutex::new(None);let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(_)=>Ok(()),NativeDecodeAllocationEvent::Post{..}=>{*verdict.lock().unwrap()=Some(Err(ValueError::literal(ValueRefusalKind::Canceled,"original post refusal")));panic!("original post interrupted after recording verdict")},_=>panic!("unexpected event")};let mut loan_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=loan_issuer.loan(&mut port);let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(5,&mut observe,&mut loan);let mut output=Vec::<u8>::new();let mut state=None;let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.allocate_vec_into(5,&mut output,&mut state)));assert!(unwind.is_err());assert_eq!(output.capacity(),5);let pending=state.as_mut().unwrap();let actual=pending.outcome.actual;assert_eq!(actual,Some(output.capacity()));native.resolve_allocation_callback(pending,verdict.lock().unwrap().take().unwrap()).unwrap();native.settle_allocation_progress(pending,actual).unwrap();assert!(native.settle_allocation_progress(pending,actual).is_err());let failure=state.take().unwrap().into_outcome().ok().unwrap().into_allocation_failure(0).unwrap();assert_eq!(failure.forwarded_post.as_ref().unwrap().message.as_ref(),"original post refusal");assert_eq!(failure.progress.admitted_bytes,5);assert_eq!(failure.progress.actual_capacity_bytes,actual);drop(native);close(output);close(failure);
}
